import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path src = Path.of("src.bin");
        Path dst = Path.of("dst.bin");

        // gather write: three buffers written by one call
        ByteBuffer head = ByteBuffer.wrap("HEAD|".getBytes(StandardCharsets.US_ASCII));
        ByteBuffer body = ByteBuffer.wrap("payload-0123456789".getBytes(StandardCharsets.US_ASCII));
        ByteBuffer tail = ByteBuffer.wrap("|TAIL".getBytes(StandardCharsets.US_ASCII));
        long written;
        try (FileChannel ch = FileChannel.open(src, StandardOpenOption.CREATE,
                StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)) {
            written = ch.write(new ByteBuffer[]{head, body, tail});
        }
        System.out.println("gather write total bytes   : " + written);
        System.out.println("file size on disk          : " + Files.size(src));

        // scatter read: one call fills several buffers
        ByteBuffer a = ByteBuffer.allocate(5);
        ByteBuffer b = ByteBuffer.allocate(18);
        ByteBuffer c = ByteBuffer.allocate(5);
        long read;
        try (FileChannel ch = FileChannel.open(src, StandardOpenOption.READ)) {
            read = ch.read(new ByteBuffer[]{a, b, c});
        }
        System.out.println("scatter read total bytes   : " + read);
        System.out.println("first buffer holds          : " + new String(a.array(), StandardCharsets.US_ASCII));
        System.out.println("middle buffer holds         : " + new String(b.array(), StandardCharsets.US_ASCII));

        // zero-copy transfer between channels
        long copied;
        try (FileChannel in = FileChannel.open(src, StandardOpenOption.READ);
             FileChannel out = FileChannel.open(dst, StandardOpenOption.CREATE,
                     StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING)) {
            copied = in.transferTo(0, in.size(), out);
        }
        System.out.println("transferTo copied bytes     : " + copied);
        System.out.println("copy identical to source    : " + (Files.mismatch(src, dst) == -1));
    }
}
